      *mask = BK7258_SYS_IRQ_GROUP0(source);
    }
  else if (source < 64)
    {
      *reg = BK7258_SYS_CPU0_INT_EN_HI;
      *mask = BK7258_SYS_IRQ_GROUP1(source);
    }
  else
    {
      return -EINVAL;
    }

  return OK;
}

static int bk7258_icu_set(unsigned int source, bool enable)
{
  uintptr_t reg;
  uint32_t mask;

  if (bk7258_icu_reg(source, &reg, &mask) < 0)
    {
      return -EINVAL;
    }

  modifyreg32(reg, mask, enable ? mask : 0);
  return ((getreg32(reg) & mask) != 0) == enable ? OK : -EIO;
}

static int bk7258_clock_gate(uint32_t mask, bool enable)
{
  modifyreg32(BK7258_SYS_DEV_CLK_EN, mask, enable ? mask : 0);
  return ((getreg32(BK7258_SYS_DEV_CLK_EN) & mask) != 0) == enable ?
         OK : -EIO;
}

static int bk7258_power_gate(uint32_t mask, bool enable)
{
  /* The Armino register is low-active: 1 means power down. */
  modifyreg32(BK7258_SYS_POWER_WAKEUP, mask, enable ? 0 : mask);
  return ((getreg32(BK7258_SYS_POWER_WAKEUP) & mask) == 0) == enable ?
         OK : -EIO;
}

int bk7258_mac_clock(bool enable)
{
  return bk7258_clock_gate(BK7258_SYS_MAC_CKEN, enable);
}

int bk7258_phy_clock(bool enable)
{
  return bk7258_clock_gate(BK7258_SYS_PHY_CKEN, enable);
}

int bk7258_mac_power(bool enable)
{
  return bk7258_power_gate(BK7258_SYS_WIFI_MAC_POWERDOWN, enable);
}

int bk7258_phy_power(bool enable)
{
  return bk7258_power_gate(BK7258_SYS_WIFI_PHY_POWERDOWN, enable);
}

int bk7258_mac_reset(void)
{
  /* Armino sys_hal_mac_subsys_reset() is explicitly TODO on BK7258. */
  return -ENOTSUP;
}

int bk7258_phy_reset(void)
{
  /* Armino sys_hal_modem_core/subsys_reset() are explicitly TODO on BK7258. */
  return -ENOTSUP;
}

int bk7258_icu_attach(unsigned int source, xcpt_t handler, void *arg)
{
  int irq = bk7258_icu_irq(source);
  return irq < 0 || handler == NULL ? -EINVAL : irq_attach(irq, handler, arg);
}

int bk7258_icu_enable(unsigned int source)
{
  int irq = bk7258_icu_irq(source);
  int ret;

  if (irq < 0)
    {
      return irq;
    }

  ret = bk7258_icu_set(source, true);
  if (ret < 0)
    {
      return ret;
    }

  up_enable_irq(irq);
  return OK;
}

int bk7258_icu_disable(unsigned int source)
{
  int irq = bk7258_icu_irq(source);
  int ret;

  if (irq < 0)
    {
      return irq;
    }

  up_disable_irq(irq);
  ret = bk7258_icu_set(source, false);
  return ret;
}

int bk7258_gpio_function(unsigned int pin, unsigned int function)
{
  uintptr_t reg;
  uint32_t mask;
  uint32_t value;

  if (pin >= BK7258_GPIO_COUNT || function > 7)
    {
      return -EINVAL;
    }

  reg = BK7258_SYS_GPIO_FUNC(pin);
  mask = BK7258_GPIO_FUNC_MASK(pin);
  value = (function & 7) << (((uint32_t)pin & 7) << 2);
  if (function == 0)
    {
      /* GPIO26/28 TXEN/RXEN use function slot 0, but must still be handed to
       * the peripheral through the AON GPIO second-function bit. */
      bk7258_gpio_periph(pin, function);
    }
  else
    {
      modifyreg32(reg, mask, value);
    }
  return (getreg32(reg) & mask) == value &&
         (function != 0 ||
          (getreg32(BK7258_GPIO_CFG(pin)) & BK7258_GPIO_CFG_SECOND_FUNC) != 0)
         ? OK : -EIO;
}

int bk7258_gpio_wifi_txen(void)
{
  /* gpio_map.h: GPIO26, GPIO_DEV_TXEN is function slot 0. */
  return bk7258_gpio_function(26, 0);
}

int bk7258_gpio_wifi_rxen(void)
{
  /* gpio_map.h: GPIO28, GPIO_DEV_RXEN is function slot 0. */
  return bk7258_gpio_function(28, 0);
}
