 21	#define BK7258_GPIO_COUNT 56
 22	
 23	static int bk7258_icu_irq(unsigned int source)
 24	{
 25	  return source < 64 ? NVIC_IRQ_FIRST + (int)source : -EINVAL;
 26	}
 27	
 28	static int bk7258_icu_reg(unsigned int source, uintptr_t *reg,
 29	                          uint32_t *mask)
 30	{
 31	  if (source < 32)
 32	    {
 33	      *reg = BK7258_SYS_CPU0_INT_EN;
 34	      *mask = BK7258_SYS_IRQ_GROUP0(source);
 35	    }
 36	  else if (source < 64)
 37	    {
 38	      *reg = BK7258_SYS_CPU0_INT_EN_HI;
 39	      *mask = BK7258_SYS_IRQ_GROUP1(source);
 40	    }
 41	  else
 42	    {
 43	      return -EINVAL;
 44	    }
 45	
 46	  return OK;
 47	}
 48	
 49	static int bk7258_icu_set(unsigned int source, bool enable)
 50	{
 51	  irqstate_t flags;
 52	  uintptr_t reg;
 53	  uint32_t mask;
 54	  int ret;
 55	
 56	  if (bk7258_icu_reg(source, &reg, &mask) < 0)
 57	    {
 58	      return -EINVAL;
 59	    }
 60	
 61	  flags = enter_critical_section();
 62	  modifyreg32(reg, mask, enable ? mask : 0);
 63	  ret = ((getreg32(reg) & mask) != 0) == enable ? OK : -EIO;
 64	  leave_critical_section(flags);
 65	  return ret;
 66	}
 67	
 68	static int bk7258_clock_gate(uint32_t mask, bool enable)
 69	{
 70	  irqstate_t flags;
 71	  int ret;
 72	
 73	  flags = enter_critical_section();
 74	  modifyreg32(BK7258_SYS_DEV_CLK_EN, mask, enable ? mask : 0);
 75	  ret = ((getreg32(BK7258_SYS_DEV_CLK_EN) & mask) != 0) == enable ?
 76	        OK : -EIO;
 77	  leave_critical_section(flags);
 78	  return ret;
 79	}
 80	
 81	static int bk7258_power_gate(uint32_t mask, bool enable)
 82	{
 83	  irqstate_t flags;
 84	  int ret;
 85	
 86	  /* The Armino register is low-active: 1 means power down. */
 87	
 88	  flags = enter_critical_section();
 89	  modifyreg32(BK7258_SYS_POWER_WAKEUP, mask, enable ? 0 : mask);
 90	  ret = ((getreg32(BK7258_SYS_POWER_WAKEUP) & mask) == 0) == enable ?
 91	        OK : -EIO;
 92	  leave_critical_section(flags);
 93	  return ret;
 94	}
 95	
 96	int bk7258_mac_clock(bool enable)
 97	{
 98	  return bk7258_clock_gate(BK7258_SYS_MAC_CKEN, enable);
 99	}
100	
101	int bk7258_phy_clock(bool enable)
102	{
103	  return bk7258_clock_gate(BK7258_SYS_PHY_CKEN, enable);
104	}
105	
106	int bk7258_mac_power(bool enable)
107	{
108	  return bk7258_power_gate(BK7258_SYS_WIFI_MAC_POWERDOWN, enable);
109	}
110	
111	int bk7258_phy_power(bool enable)
112	{
113	  return bk7258_power_gate(BK7258_SYS_WIFI_PHY_POWERDOWN, enable);
114	}
115	
116	int bk7258_mac_reset(void)
117	{
118	  /* Armino sys_hal_mac_subsys_reset() is explicitly TODO on BK7258. */
119	  return -ENOTSUP;
120	}
121	
122	int bk7258_phy_reset(void)
123	{
124	  /* Armino sys_hal_modem_core/subsys_reset() are explicitly TODO on BK7258. */
125	  return -ENOTSUP;
126	}
127	
128	int bk7258_icu_attach(unsigned int source, xcpt_t handler, void *arg)
129	{
130	  int irq = bk7258_icu_irq(source);
131	  return irq < 0 || handler == NULL ? -EINVAL : irq_attach(irq, handler, arg);
132	}
133	
134	int bk7258_icu_enable(unsigned int source)
135	{
136	  int irq = bk7258_icu_irq(source);
137	  int ret;
138	
139	  if (irq < 0)
140	    {
141	      return irq;
142	    }
143	
144	  ret = bk7258_icu_set(source, true);
145	  if (ret < 0)
146	    {
147	      return ret;
148	    }
149	
150	  up_enable_irq(irq);
151	  return OK;
152	}
153	
154	int bk7258_icu_disable(unsigned int source)
155	{
156	  int irq = bk7258_icu_irq(source);
157	  int ret;
158	
159	  if (irq < 0)
160	    {
161	      return irq;
162	    }
163	
164	  up_disable_irq(irq);
165	  ret = bk7258_icu_set(source, false);
166	  return ret;
167	}
168	
169	static int bk7258_gpio_wifi_mux(unsigned int pin)
170	{
171	  irqstate_t flags;
172	  uintptr_t reg;
173	  uint32_t mask;
174	  int ret;
175	
176	  if (pin >= BK7258_GPIO_COUNT)
177	    {
178	      return -EINVAL;
179	    }
180	
181	  reg = BK7258_SYS_GPIO_FUNC(pin);
182	  mask = BK7258_GPIO_FUNC_MASK(pin);
183	
184	  /* GPIO26/TXEN and GPIO28/RXEN are both function slot 0 in Armino's
185	   * gpio_map.h.  Configure the selector and pad ownership as one operation. */
186	
187	  flags = enter_critical_section();
188	  bk7258_gpio_periph(pin, 0);
189	  ret = (getreg32(reg) & mask) == 0 &&
190	        (getreg32(BK7258_GPIO_CFG(pin)) &
191	         BK7258_GPIO_CFG_SECOND_FUNC) != 0 ? OK : -EIO;
192	  leave_critical_section(flags);
193	  return ret;
194	}
195	
196	int bk7258_gpio_wifi_txen(void)
197	{
198	  /* gpio_map.h: GPIO26, GPIO_DEV_TXEN is function slot 0. */
199	  return bk7258_gpio_wifi_mux(26);
200	}
201	
202	int bk7258_gpio_wifi_rxen(void)
203	{
204	  /* gpio_map.h: GPIO28, GPIO_DEV_RXEN is function slot 0. */
205	  return bk7258_gpio_wifi_mux(28);
206	}
