/****************************************************************************
 * chips/bk7258/bk7258_clock.c
 ****************************************************************************/

#include <nuttx/config.h>

#include "arm_internal.h"
#include "bk7258_internal.h"
#include "include/bk7258_memorymap.h"

void bk7258_clock_uart0(void)
{
  /* The secure Bootloader owns CPU/Flash clock setup for L0.  This layer only
   * enables the confirmed UART0 device clock and selects its independent
   * 26 MHz XTAL source. */

  uint32_t regval;

  /* This runs before NuttX's scheduler/locking initialization. */

  regval = getreg32(BK7258_SYS_DEV_CLK_EN);
  putreg32(regval | BK7258_SYS_UART0_CLK_EN, BK7258_SYS_DEV_CLK_EN);

  regval = getreg32(BK7258_SYS_CLKDIV1);
  putreg32(regval & ~BK7258_SYS_UART0_XTAL, BK7258_SYS_CLKDIV1);
}
/****************************************************************************
 * chips/bk7258/bk7258_irq.c
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdint.h>

#include <nuttx/arch.h>
#include <nuttx/irq.h>

#include "arm_internal.h"
#include "nvic.h"
#include "bk7258_internal.h"

extern const void *const _vectors[];

static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
                          uintptr_t offset)
{
  int external;

  if (irq >= NVIC_IRQ_FIRST && irq < NR_IRQS)
    {
      external = irq - NVIC_IRQ_FIRST;
      *regaddr = NVIC_IRQ_ENABLE(external) + offset;
      *bit = UINT32_C(1) << (external & 31);
      return OK;
    }

  if (irq == NVIC_IRQ_SYSTICK)
    {
      *regaddr = NVIC_SYSTICK_CTRL;
      *bit = NVIC_SYSTICK_CTRL_ENABLE;
      return OK;
    }

  return -EINVAL;
}

int up_prioritize_irq(int irq, int priority)
{
  uintptr_t regaddr;
  uint32_t regval;
  int shift;

  if (irq < 0 || irq >= NR_IRQS || priority < 0 || priority > 0xff)
    {
      return -EINVAL;
    }

  if (irq < NVIC_IRQ_FIRST)
    {
      if (irq < 4)
        {
          return -EINVAL;
        }

      regaddr = NVIC_SYSH_PRIORITY(irq);
      irq -= 4;
    }
  else
    {
      irq -= NVIC_IRQ_FIRST;
      regaddr = NVIC_IRQ_PRIORITY(irq);
    }

  shift = (irq & 3) << 3;
  regval = getreg32(regaddr);
  regval &= ~(UINT32_C(0xff) << shift);
  regval |= (uint32_t)priority << shift;
  putreg32(regval, regaddr);
  return OK;
}

void up_disable_irq(int irq)
{
  uintptr_t regaddr;
  uint32_t bit;

  if (bk7258_irqinfo(irq, &regaddr, &bit,
                      NVIC_IRQ0_31_CLEAR - NVIC_IRQ0_31_ENABLE) == OK)
    {
      if (irq >= NVIC_IRQ_FIRST)
        {
          putreg32(bit, regaddr);
        }
      else
        {
          modifyreg32(regaddr, bit, 0);
        }
    }
}

void up_enable_irq(int irq)
{
  uintptr_t regaddr;
  uint32_t bit;

  if (bk7258_irqinfo(irq, &regaddr, &bit, 0) == OK)
    {
      if (irq >= NVIC_IRQ_FIRST)
        {
          putreg32(bit, regaddr);
        }
      else
        {
          modifyreg32(regaddr, 0, bit);
        }
    }
}

void arm_ack_irq(int irq)
{
  (void)irq;
}

void up_irqinitialize(void)
{
  int irq;

  for (irq = 0; irq < NR_IRQS - NVIC_IRQ_FIRST; irq += 32)
    {
      putreg32(UINT32_MAX, NVIC_IRQ_CLEAR(irq));
      putreg32(UINT32_MAX, NVIC_IRQ_CLRPEND(irq));
    }

  putreg32((uintptr_t)_vectors, NVIC_VECTAB);
  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
  irq_attach(NVIC_IRQ_BUSFAULT, arm_busfault, NULL);
  irq_attach(NVIC_IRQ_USAGEFAULT, arm_usagefault, NULL);
  irq_attach(NVIC_IRQ_SECUREFAULT, arm_securefault, NULL);

  modifyreg32(NVIC_SYSHCON, 0,
              NVIC_SYSHCON_MEMFAULTENA | NVIC_SYSHCON_BUSFAULTENA |
              NVIC_SYSHCON_USGFAULTENA | NVIC_SYSHCON_SECUREFAULTENA);
  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);

  /* SVC drives NuttX thread-mode context switches. It must remain above the
   * BASEPRI level used to mask normal interrupts in critical sections. */

  up_prioritize_irq(NVIC_IRQ_SVCALL, NVIC_SYSH_SVCALL_PRIORITY);
  up_irq_enable();
}
/****************************************************************************
 * chips/bk7258/bk7258_gpio.c
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>

#include "arm_internal.h"
#include "bk7258_internal.h"
#include "include/bk7258_memorymap.h"

static void bk7258_gpio_uart0(unsigned int pin)
{
  uint32_t regval;

  /* GPIO11 uses peripheral function slot 0 for UART0 TX.  The per-pin GPIO
   * control enables the second function, disables GPIO ownership and keeps
   * the vendor's pull-up setting. */

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~(UINT32_C(3) << 2);
  regval |=  (UINT32_C(2) << 2);
  regval &= ~(UINT32_C(3) << 4);
  regval |=  (UINT32_C(3) << 4);
  regval |=  (UINT32_C(1) << 6);
  putreg32(regval, BK7258_GPIO_CFG(pin));

  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
}

void bk7258_gpio_uart0_tx(void)
{
  bk7258_gpio_uart0(BK7258_GPIO11);
}

void bk7258_gpio_uart0_rx(void)
{
  bk7258_gpio_uart0(10);
}

/****************************************************************************
 * Name: bk7258_gpio_select_func
 *
 * Description:
 *   Route the pin to its plain GPIO function (peripheral mux field = 0).
 *
 ****************************************************************************/

static void bk7258_gpio_select_func(unsigned int pin)
{
  uint32_t regval;
  uint32_t reg  = BK7258_SYS_GPIO_FUNC(pin);
  uint32_t mask = BK7258_GPIO_FUNC_MASK(pin);

  regval  = getreg32(reg);
  regval &= ~mask;
  putreg32(regval, reg);
}

/****************************************************************************
 * Name: bk7258_gpio_periph
 *
 * Description:
 *   Route the pin to a peripheral (second) function selected by the 4-bit
 *   per-pin mux field (see the Armino SDK gpio_map.h table, e.g. option 0
 *   on GPIO2/4 is the SPI1 SCK/MOSI).  The per-pin GPIO control is set to
 *   I/O-disable plus second-function so the peripheral owns the pad.
 *
 ****************************************************************************/

void bk7258_gpio_periph(unsigned int pin, unsigned int func)
{
  uint32_t regval;

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~(UINT32_C(3) << 2);        /* clear IO mode */
  regval |=  (UINT32_C(2) << 2);        /* I/O disable: peripheral drives */
  regval &= ~(UINT32_C(3) << 4);        /* clear pull */
  regval |=  (UINT32_C(1) << 6);        /* second function enable */
  regval &= ~BK7258_GPIO_CFG_OUTPUT_EN;
  regval &= ~BK7258_GPIO_CFG_INPUT_EN;
  putreg32(regval, BK7258_GPIO_CFG(pin));

  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
  regval |=  (func & UINT32_C(0xf)) << (((uint32_t)(pin) & 7) << 2);
  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
}

/****************************************************************************
 * Name: bk7258_gpio_config_output
 *
 * Description:
 *   Configure the GPIO pin as a push-pull output with no pull resistor.
 *
 ****************************************************************************/

void bk7258_gpio_config_output(unsigned int pin)
{
  uint32_t regval;

  bk7258_gpio_select_func(pin);

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~BK7258_GPIO_CFG_MODE_MASK;
  regval |= BK7258_GPIO_CFG_MODE_OUTPUT;
  regval &= ~BK7258_GPIO_CFG_PULL_MASK;
  regval &= ~BK7258_GPIO_CFG_SECOND_FUNC;
  regval &= ~BK7258_GPIO_CFG_OUTPUT_EN;  /* LOW active: 0 = output enabled */
  regval &= ~BK7258_GPIO_CFG_INPUT_EN;   /* disable input path */
  putreg32(regval, BK7258_GPIO_CFG(pin));
}

/****************************************************************************
 * Name: bk7258_gpio_config_input
 *
 * Description:
 *   Configure the GPIO pin as an input with optional pull-up.
 *
 ****************************************************************************/

void bk7258_gpio_config_input(unsigned int pin)
{
  uint32_t regval;

  bk7258_gpio_select_func(pin);

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~BK7258_GPIO_CFG_MODE_MASK;
  regval |= BK7258_GPIO_CFG_MODE_INPUT;
  regval &= ~BK7258_GPIO_CFG_PULL_MASK;
  regval |= BK7258_GPIO_CFG_PULL_UP;
  regval &= ~BK7258_GPIO_CFG_SECOND_FUNC;
  regval |= BK7258_GPIO_CFG_OUTPUT_EN;  /* disable output path */
  regval |= BK7258_GPIO_CFG_INPUT_EN;   /* HIGH active: 1 = input enabled */
  putreg32(regval, BK7258_GPIO_CFG(pin));
}

/****************************************************************************
 * Name: bk7258_gpio_write
 *
 * Description:
 *   Drive a GPIO output pin to the requested level.
 *
 ****************************************************************************/

void bk7258_gpio_write(unsigned int pin, bool high)
{
  uint32_t regval;

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  if (high)
    {
      regval |= BK7258_GPIO_CFG_DATA;
    }
  else
    {
      regval &= ~BK7258_GPIO_CFG_DATA;
    }

  putreg32(regval, BK7258_GPIO_CFG(pin));
}

/****************************************************************************
 * Name: bk7258_gpio_read
 *
 * Description:
 *   Sample the level of a GPIO pin configured as an input.
 *
 ****************************************************************************/

bool bk7258_gpio_read(unsigned int pin)
{
  return (getreg32(BK7258_GPIO_CFG(pin)) & BK7258_GPIO_CFG_DATA) != 0;
}
# BK7258 CP/AP common chip component.

set(SRCS
    bk7258_irq.c
    bk7258_allocateheap.c
    bk7258_timer.c
    bk7258_ap_boot.c)

