static void bk7258_lcd_hw_reset(void)
{
  bk7258_gpio_config_output(BOARD_LCD_RST_PIN);

  bk7258_gpio_write(BOARD_LCD_RST_PIN, false);
  up_mdelay(20);
  bk7258_gpio_write(BOARD_LCD_RST_PIN, true);
  up_mdelay(120);
