 *   lcd_dev_s container pointer stays valid.
 *
 ****************************************************************************/

static int bk7258_lcd_setpower(FAR struct lcd_dev_s *dev, int power)
{
  int ret;

  ret = g_lcd_setpower(dev, power);
  if (ret == OK)
